/* the real command / tool card */
function commandCard({ label, command, output, exitCode, status }) {
  const failed = (typeof exitCode === 'number' && exitCode !== 0) || status === 'failed';
  const card = document.createElement('div');
  card.className = 'group flex flex-col overflow-hidden rounded-lg border border-strong bg-secondary-soft-alpha';
  card.innerHTML =
    '<div class="flex flex-col overflow-clip rounded-none border-none">' +
      `<div class="flex items-center justify-between gap-2 px-2 py-1 font-sans text-sm text-codex-description select-none"><span>${esc(label)}</span>${
        failed ? '<span class="text-red-500">failed</span>' : ''}</div>` +
      '<div class="relative overflow-hidden"><div class="relative">' +
        '<div class="px-2 pt-2">' +
          '<div class="group/command relative pe-6">' +
            `<div role="button" tabindex="0" class="cursor-interaction rounded-md bg-transparent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-0 text-size-chat-sm text-codex-description whitespace-pre-wrap break-words font-code line-clamp-2" aria-label="$ ${esc(command)}">` +
              '<span class="me-[1ch] text-tertiary">$</span>' +
              `<code class="contents"><span>${esc(command)}</span></code>` +
            '</div>' +
            `<button type="button" class="no-drag cursor-interaction focus-visible:outline-hidden whitespace-nowrap flex border gap-1 rounded-full electron:rounded-md text-tertiary not-disabled:not-aria-disabled:hover:bg-secondary-ghost-hover border-transparent electron:p-1 button-icon items-center justify-center p-0.5 absolute top-0 right-0 opacity-0 transition-opacity duration-basic group-hover/command:opacity-100 focus-visible:opacity-100" aria-label="复制" data-copy>${ICON16.copy}</button>` +
          '</div>' +
        '</div>' +
        (output
          ? '<div class="group/output relative min-h-[1.25rem] pe-0">' +
              '<div class="vertical-scroll-fade-mask max-h-36 [--edge-fade-distance:2rem] box-border flex flex-col-reverse overflow-x-auto overflow-y-auto whitespace-pre font-code font-medium text-codex-description text-size-chat-sm">' +
                `<div class="w-max min-w-full p-2"><code class="text-codex-description">${esc(output)}</code></div>` +
              '</div>' +
            '</div>'
          : '') +
      '</div></div>' +
    '</div>';

  const copyBtn = card.querySelector('[data-copy]');
