.workspace-menu { position: absolute; z-index: 50; top: calc(100% - 4px); left: 8px; width: calc(100% - 16px); padding: 6px; border: .8px solid var(--color-border-strong); border-radius: 12.5px; background: var(--app-color-background-elevated-primary); box-shadow: var(--shadow-lg); overflow: hidden; transition: height .15s var(--ease-out), opacity .15s var(--ease-out); }
