.workspace-menu-empty { margin: 8px; color: var(--muted); font-size: 13px; line-height: 20px; }

/* Transcript stays continuous; execution detail floats above it. */
.conversation-shell { position: relative; display: flex; flex-direction: column; min-width: 0; min-height: 0; margin: 0 4px 4px 0; background: var(--app-color-background-surface); }
.chat-workspace { position: relative; display: grid; grid-template-columns: minmax(0,1fr) var(--preview-divider-width,0px) minmax(0,var(--preview-current-width,0%)); min-width: 0; min-height: 0; overflow: hidden; margin: 0 4px 4px 0; border: .8px solid var(--color-border-subtle); border-radius: 12.5px; background: var(--app-color-background-surface); }
