.preview-close { font-size: 20px; }
.preview-toolbar { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; min-height: 48px; padding: 7px 10px; border-bottom: 1px solid var(--color-border-subtle); }
.preview-breadcrumb { display: flex; align-items: center; gap: 8px; min-width: 0; flex: 1 1 100px; width: fit-content; max-width: 100%; padding: 7px 10px; overflow: hidden; border: .8px solid var(--color-border-subtle); border-radius: 999px; box-shadow: 0 2px 5px rgba(13,13,13,.025); color: var(--muted); font-size: 12px; white-space: nowrap; }
