.preview-breadcrumb-part > span:last-child, .preview-breadcrumb-part > strong { min-width: 0; overflow: hidden; text-overflow: ellipsis; font-weight: 400; }
.preview-breadcrumb-part > strong { color: var(--color-text); font-weight: 500; }
.preview-breadcrumb-part:last-child { flex-shrink: 0; max-width: 65%; }
.preview-view-actions { display: flex; align-items: center; gap: 5px; margin-left: auto; }
.preview-view-actions button { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 32px; padding: 5px 10px; border: .8px solid var(--color-border-subtle); border-radius: 999px; background: var(--app-color-background-surface); box-shadow: 0 2px 5px rgba(13,13,13,.025); font-size: 12px; line-height: 20px; white-space: nowrap; }
