.preview-content { display: grid; grid-template-columns: minmax(0,1fr); flex: 1; min-width: 0; min-height: 0; }
.with-file-tree .preview-content { grid-template-columns: minmax(0,1fr) clamp(170px,28%,244px); }
.is-expanded.with-file-tree .preview-content { grid-template-columns: minmax(0,1fr) clamp(260px,44%,560px); }
.is-expanded .preview-tab > [role="tab"] { font-size: 14px; }
.is-expanded .preview-breadcrumb, .is-expanded .preview-view-actions button { font-size: 14px; }
.is-expanded .preview-breadcrumb { flex: 0 1 auto; max-width: min(65%,680px); }
.is-expanded .file-tree-row, .is-expanded .file-tree-section-heading { min-height: 30px; font-size: 14px; line-height: 21px; }
.is-expanded .file-tree-all-changes, .is-expanded .file-tree-search input { font-size: 14px; }
.preview-document, .file-tab-panel, .document-pane, .document-main, .document-source { display: flex; flex-direction: column; flex: 1; min-width: 0; min-height: 0; overflow: hidden; }
.document-rendered { flex: 1; min-height: 0; overflow: auto; padding: 20px 24px 48px; overscroll-behavior: contain; }
.file-markdown { position: relative; font-size: 14px; line-height: 22px; overflow-wrap: anywhere; }
