.preview-feedback { position: absolute; z-index: 4; top: 102px; right: 16px; padding: 7px 12px; border: .8px solid var(--color-border); border-radius: 10px; background: var(--app-color-background-control); box-shadow: var(--shadow-sm); color: var(--color-text-secondary); font-size: 12px; pointer-events: none; }
.preview-file-tree { display: flex; flex-direction: column; min-height: 0; min-width: 0; padding-top: 8px; border-left: .8px solid var(--color-border-subtle); }
