.file-tree-section-heading > span:nth-child(2) { flex: 1; min-width: 0; }
.file-tree-section-heading:hover { background: var(--color-background-secondary-ghost-hover); }
.changed-directory-dot { display: block; flex: none; width: 5px; height: 5px; margin-right: 6px; border-radius: 50%; background: var(--color-text-accent); opacity: .6; }
.file-tree-scroll { flex: 1; min-height: 0; overflow: auto; padding: 0 5px 20px; overscroll-behavior: contain; }
.file-tree-row { display: flex; align-items: center; gap: 6px; width: 100%; min-width: 0; min-height: 28px; padding: 4px 6px; border: 0; border-radius: 7.5px; background: transparent; text-align: start; font-size: 12px; line-height: 20px; }
.file-tree-row:hover, .file-tree-row.selected { background: var(--color-background-secondary-ghost-hover); }
.file-tree-row.selected { color: var(--color-text-accent); }
.file-tree-row > span:not(.file-tree-chevron):not(.file-change-status) { min-width: 0; flex: 1; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.file-tree-row > svg { flex: none; color: var(--muted); }
.file-tree-row[data-status*="M"], .file-tree-row[data-status*="R"] { color: var(--color-text-accent); }
