.file-tree-chevron { display: inline-flex; align-items: center; justify-content: center; flex: none; width: 8px; color: var(--muted); transition: transform .15s var(--ease-out); }
.file-tree-chevron[data-expanded="true"] { transform: rotate(90deg); }
.tree-notice, .file-tree-caption { margin: 8px; color: var(--muted); font-size: 11px; line-height: 18px; overflow-wrap: anywhere; }
