.file-added, .file-removed { flex: none; font-size: 10px; font-variant-numeric: tabular-nums; }
.file-added { color: var(--color-git-added); }
.file-removed { color: var(--color-git-removed); }
.file-import-button { margin: 6px 8px 10px; padding: 6px; border: .8px solid var(--color-border); border-radius: 7.5px; background: none; color: var(--muted); font-size: 11px; }
.file-import-button:hover { color: var(--color-text); background: var(--color-background-secondary-ghost-hover); }
.binary-preview { display: flex; flex-direction: column; flex: 1; min-height: 0; }
.binary-toolbar { display: flex; justify-content: space-between; gap: 12px; flex: none; padding: 8px 16px; border-bottom: .8px solid var(--color-border-subtle); color: var(--muted); font-size: 12px; }
