    const directories = {
      '': [entry('src', true), entry('README.md'), entry('deleted.txt')],
      src: [entry('src/nested', true), entry('src/main.ts'), entry('src/new.ts'), entry('src/unchanged.ts')],
      'src/nested': [entry('src/nested/deep.ts')],
